    private Identifier texture;

    public MyScreen() {
        super();
        rotation = 0.0f;
        texture = new Identifier("modid", "textures/cube.png");
    }

    @Override
    public void render(MatrixStack matrices, int mouseX, int mouseY, float delta) {
        // 清除屏幕
        clearScreen();

        // 更新旋转角度
        rotation += delta * 0.5f;
        if (rotation >= 360.0f) {
            rotation -= 360.0f;
        }

        // 设置透视投影矩阵
        setupPerspective();

        // 绘制旋转的正方体
        drawRotatingCube(matrices, delta);
