    private void clearScreen() {
        renderBackground();
    }

    private void setupPerspective() {
        float aspectRatio = (float) width / (float) height;
        GL11.glMatrixMode(GL11.GL_PROJECTION);
        GL11.glLoadIdentity();
        GL11.glFrustum(-aspectRatio, aspectRatio, -1.0f, 1.0f, 1.0f, 1000.0f);
        GL11.glMatrixMode(GL11.GL_MODELVIEW);
        GL11.glLoadIdentity();
    }

    private void drawRotatingCube(MatrixStack matrices, float delta) {
        // 开始渲染
